import{_ as n,l as o,o as e,c as s,v as t,p as l,x as i,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"静态与污点分析","description":"","frontmatter":{"title":"静态与污点分析","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/static-taint-analysis.md","filePath":"cs/static-taint-analysis.md","lastUpdated":1789023840000}'),p={name:"cs/static-taint-analysis.md"};function _(u,a,m,E,S,f){const r=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="静态与污点分析" tabindex="-1">静态与污点分析 <a class="header-anchor" href="#静态与污点分析" aria-label="Permalink to &quot;静态与污点分析&quot;">​</a></h1><div class="epigraph"><p>污点把「不可信来源」标到字节上，看它是否流进「危险汇点」。静态分析不执行程序，因此必须抽象；假阳性是税，假阴性是洞。</p><footer>—— 据 Denning 的信息流；Schwartz, Avgerinos and Brumley 对污点的 SoK；Soot/CodeQL 一类工程</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/symbolic-execution">KLEE</a>沿路径跑。缺口是<strong>不执行也能问流</strong>：源→汇。本课收污点与静态告警的合同，不把 CodeQL 查询写成对外部目标的作战。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>命令注入、SQL、XSS 在 Web 课会再出现：共同形状是不可信数据进解释器。污点：源（输入）、汇（exec/SQL）、净化器。静态：控制流图上的近似。缺口是抽象与净化器是否真净化。</p><h3 id="净化器撒谎" tabindex="-1">净化器撒谎 <a class="header-anchor" href="#净化器撒谎" aria-label="Permalink to &quot;净化器撒谎&quot;">​</a></h3><p>黑名单替换不是净化。污点会信你标注的 sanitizer。</p><p><span class="marginnote">Denning；BitBlaze/TaintCheck 一类动态污点点名。本课禁止扫描他人站点。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画源–汇。对照动态污点（运行时，开销）与静态（编译期，近似）。下一课 sanitizer：把未定义行为变成可 fuzz 的崩溃。</p>',12)),(e(),l(h,null,{default:i(()=>[c(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E4%B8%8D%E5%8F%AF%E4%BF%A1%E6%BA%90%22%5D%20--%3E%20FLOW%5B%22%E6%95%B0%E6%8D%AE%E6%B5%81%22%5D%0A%20%20FLOW%20--%3E%20SNK%5B%22%E5%8D%B1%E9%99%A9%E6%B1%87%E7%82%B9%22%5D%0A%20%20SAN%5B%22%E7%9C%9F%E5%87%80%E5%8C%96%22%5D%20--%3E%20CUT%5B%22%E5%88%87%E6%96%AD%E6%B1%A1%E7%82%B9%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>发现要可编码成规则。下一课 ASan/UBSan/MSan 把一类空间/未定义错误变成确定失败。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给绕过 WAF 的污点例子。Sanitizers 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>符号执行跑路径；污点问源是否到汇。</li><li>静态要抽象；净化器标注会撒谎。</li><li>与 Web 解释器洞同形。</li><li>下一课 Sanitizers。</li><li>出处：Denning；Schwartz, Avgerinos and Brumley；对照 CodeQL 文档。</li></ul>',8))])}const b=n(p,[["render",_]]);export{B as __pageData,b as default};
